/* Ace Editor Styles - Matching Figma Design */
.ace-editor-wrapper .ace_editor {
  background: transparent !important;
  font-family: 'Geist Mono', monospace !important;
  font-size: 12px !important;
  line-height: 1.5 !important;
  color: var(--app-text-primary) !important;
}

.ace-editor-wrapper .ace_content {
  background: transparent !important;
}

.ace-editor-wrapper .ace_gutter {
  background: transparent !important;
}

.ace-editor-wrapper .ace_scroller {
  background: transparent !important;
}

/* Override Ace theme backgrounds for seamless integration */
.ace-editor-wrapper .ace-github {
  background-color: transparent !important;
  color: var(--app-text-primary) !important;
}

.ace-editor-wrapper .ace-monokai {
  background-color: transparent !important;
  color: var(--app-text-primary) !important;
}

.ace-editor-wrapper .ace-github .ace_cursor,
.ace-editor-wrapper .ace-monokai .ace_cursor {
  color: var(--app-text-primary) !important;
}

.ace-editor-wrapper .ace_active-line {
  background: transparent !important;
}

/* Velt Comment Marker Styles (Ace-specific) */
.ace-velt-comment-marker {
  position: absolute;
  background-color: rgba(255, 208, 0, 0.3) !important;
  border-bottom: 2px solid #ffd000;
  cursor: pointer;
  z-index: 1;
}

.ace-velt-comment-marker.velt-comment-selected {
  background-color: rgba(255, 208, 0, 0.5) !important;
}

velt-comment-text {
  background-color: rgba(255, 208, 0, 0.3);
  border-bottom: 2px solid #ffd000;
  cursor: pointer;
}

velt-comment-text.velt-comment-selected {
  background-color: rgba(255, 208, 0, 0.5);
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
